import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const sources = ["budget.js", "food-pricing.js", "destinations.js", "restaurants.js", "transport.js", "app.js"];
const parts = [];
for (const name of sources) {
  const source = await readFile(join(root, "js", name), "utf8");
  parts.push(`// ${name}\n${source.replace(/^import .*?;\r?\n/gm, "").replace(/^export /gm, "")}`);
}
const bundle = `// Generated by scripts/build-app-bundle.mjs. Edit the source modules instead.\n(() => {\n${parts.slice(0, 3).join("\n")}\nconst buildDestinationCandidates = generateDestinationCandidates;\n${parts.slice(3).join("\n")}\n})();\n`;
await writeFile(join(root, "js", "app.bundle.js"), bundle, "utf8");
